// Detectar y procesar el tipo de media
const body = $json.body || $json;
const mediaType = body.media_type || 'text';
const mediaUrl = body.media_url || '';
const phone = body.phone || '';
const name = body.name || '';
const message = body.message || '';
const timestamp = body.timestamp || new Date().toISOString();

let processedData = {
  phone,
  name,
  message,
  timestamp,
  media_type: mediaType,
  media_url: mediaUrl,
  has_media: mediaType !== 'text' && mediaType !== '' && mediaUrl !== ''
};

// Si es audio, extraer el base64 y mime type
if (mediaType === 'audio' && mediaUrl) {
  if (mediaUrl.startsWith('data:')) {
    const matches = mediaUrl.match(/^data:([^;]+);base64,(.+)$/);
    if (matches) {
      processedData.audio_mime_type = matches[1];
      processedData.audio_base64 = matches[2];
    }
  }
}

// Si es imagen, extraer base64 y mime type
if (mediaType === 'image' && mediaUrl) {
  if (mediaUrl.startsWith('data:')) {
    const matches = mediaUrl.match(/^data:([^;]+);base64,(.+)$/);
    if (matches) {
      processedData.image_mime_type = matches[1];
      processedData.image_base64 = matches[2];
    }
  }
  processedData.image_data = mediaUrl;
}

// Determinar ruta
let route = 'text';
if (mediaType === 'audio') route = 'audio';
else if (mediaType === 'image') route = 'image';
else if (mediaType === 'video' || mediaType === 'document') route = 'unsupported';

processedData.route = route;

return [{ json: processedData }];

let transcription = '';

try {
  // Estructura que devuelve el nodo Gemini de n8n
  if ($json.content && $json.content.parts && $json.content.parts[0]) {
    transcription = $json.content.parts[0].text || '';
  }
  // Fallback por si acaso viene la estructura REST clásica
  else if ($json.candidates && $json.candidates[0]) {
    transcription = $json.candidates[0].content.parts[0].text || '';
  }
} catch (e) {
  transcription = 'No se pudo transcribir el audio';
}

const originalData = $('Es Audio?').first().json;

return [{
  json: {
    phone: originalData.phone,
    name: originalData.name,
    timestamp: originalData.timestamp,
    media_type: 'audio',
    original_message: originalData.message,
    transcription: transcription.trim(),
    ai_message: `[Nota de voz transcrita]: ${transcription.trim()}`,
    unsupported_media: false
  }
}];

// Para video y documentos - respuesta por defecto
return [{
  json: {
    phone: $json.phone,
    name: $json.name,
    timestamp: $json.timestamp,
    media_type: $json.media_type,
    original_message: $json.message,
    ai_message: $json.message,
    unsupported_media: true,
    default_response: `¡Hola hermosa! 🌿✨ Recibí tu ${$json.media_type === 'video' ? 'video' : 'documento'}, pero por el momento no puedo procesarlo. ¿Podrías contarme en texto o con una nota de voz qué necesitas? 💚🌸`
  }
}];

// Texto normal sin media
return [{
  json: {
    phone: $json.phone,
    name: $json.name,
    timestamp: $json.timestamp,
    media_type: 'text',
    original_message: $json.message,
    ai_message: $json.message,
    unsupported_media: false
  }
}];

// Usar respuesta predefinida para media no soportada
return [{
  json: {
    output: $json.default_response,
    phone: $json.phone,
    name: $json.name,
    media_type: $json.media_type
  }
}];

// 1. Extraer el output inicial
const output = $('AI Agent').first().json.output;
let result;
if (Array.isArray(output)) {
  result = output[0];
} else {
  result = output;
}

// 2. EXTRAER Y BORRAR EL TAG DEL TEXTO
let tag = null;
const regex = /\{tag:(.*?)\}/i;
// Nos aseguramos que result sea texto continuo
if (typeof result === 'string') {
  const match = result.match(regex);
  if (match) {
    tag = match[1].trim(); // Guardamos lo que extrajo (ej: "Agendar")
    result = result.replace(regex, '').trim(); // Borramos el texto del tag del mensaje real
  }
}

// 3. Tomar la data original
const originalData = $('Es Media No Soportada?').first().json;

// 4. Retornar todo de vuelta en el json
return [{
  json: {
    output: result, // Este output ahora ya NO tiene el texto de la etiqueta
    phone: originalData.phone,
    name: originalData.name,
    media_type: originalData.media_type,
    tag: tag // <--- Aquí pasamos la nueva propiedad con la etiqueta
  }
}];

// Merge final - preparar para respuesta
const data = $json;

return [{
  json: {
    output: data.output,
    phone: data.phone,
    name: data.name,
    media_type: data.media_type,
    tag:data.tag
  }
}];

const items = $input.all();

const results = [];

for (const item of items) {
  let raw = '';
  let cleaned = '';
  let parsed = {};

  try {
    // 🔥 detectar estructura (OpenAI vs Gemini)
    raw =
      item.json?.output?.[0]?.content?.[0]?.text ||
      item.json?.candidates?.[0]?.content?.parts?.[0]?.text ||
      item.json?.text ||
      '';

    // 🔥 limpiar markdown ```json
    cleaned = raw
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();

    // 🔥 parsear JSON
    parsed = JSON.parse(cleaned);

  } catch (e) {
    parsed = { tipo: 'error', raw };
  }

  const originalData = $('Es Imagen?').first().json;

  results.push({
    json: {
      phone: originalData.phone,
      name: originalData.name,
      timestamp: originalData.timestamp,
      media_type: 'image',
      original_message: originalData.message,

      image_analysis: parsed,

      ai_message: generarMensaje(parsed, originalData.message),

      unsupported_media: false
    }
  });
}

return results;


// 🔥 generador de mensaje
function generarMensaje(parsed, userMessage) {
  if (parsed.tipo === 'abono') {
    return `El usuario envió un comprobante de pago:
Referencia: ${parsed.referencia}
Valor: ${parsed.valor}
Fecha: ${parsed.fecha}
Destino: ${parsed.destino}`;
  }

  if (parsed.tipo === 'cabello') {
    return `El usuario envió una imagen de su cabello. ${parsed.mensaje}`;
  }

  return `No se pudo interpretar la imagen correctamente. Mensaje usuario: ${userMessage}`;
}
